// Points-based regime (live Jan 2023): threshold by stagger
//   Annual stagger = 2 points · Quarterly = 4 · Monthly = 5
// At threshold, £200 fixed penalty + £200 for each further default until clean record.
const THRESHOLDS = { annual: 2, quarterly: 4, monthly: 5 };
const out = [];
const byCustomer = {};
for (const row of items.map(i => i.json)) {
  const key = row.customer_id;
  if (!byCustomer[key]) byCustomer[key] = { rows: [], customer: row.vat_customers || {} };
  byCustomer[key].rows.push(row);
}
const now = new Date();
const TWO_YEARS_MS = 1000 * 60 * 60 * 24 * 365 * 2;
for (const [customer_id, bucket] of Object.entries(byCustomer)) {
  const stagger = (bucket.customer.stagger || 'quarterly').toLowerCase();
  const threshold = THRESHOLDS[stagger] || 4;
  // Live points = points unexpired within rolling 24m window
  const live = bucket.rows.filter(r => r.expires_at && (new Date(r.expires_at) > now)).length;
  // Forecast: project next 24m late-filings using last 12m rate
  const last12mLate = bucket.rows.filter(r => r.created_at && ((now - new Date(r.created_at)) < TWO_YEARS_MS / 2)).length;
  const forecast_24m = live + last12mLate * 2;
  let band = 'green';
  if (live >= threshold) band = 'red';
  else if (live === threshold - 1) band = 'red';
  else if (live === threshold - 2) band = 'amber';
  out.push({ json: {
    customer_id,
    customer_legal_name: bucket.customer.legal_name,
    customer_email: bucket.customer.contact_email,
    customer_vrn: bucket.customer.vat_number,
    stagger,
    threshold,
    live_points: live,
    forecast_24m,
    band,
    fixed_penalty_at_threshold_gbp: 200,
    further_default_penalty_gbp: 200,
    insurance_cross_sell_eligible: band === 'red'
  } });
}
return out;
